<?php
$id=(int)get('id');$stmt=db()->prepare('SELECT p.*,w.nama_lengkap,w.nik,w.alamat,w.no_hp,w.user_id FROM pengajuan p JOIN data_warga w ON w.id=p.data_warga_id WHERE p.id=?');$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){set_flash('danger','Pengajuan tidak ditemukan.');redirect('pengajuan');}
$files=db()->prepare('SELECT * FROM pengajuan_berkas WHERE pengajuan_id=? ORDER BY created_at');$files->execute([$id]);$files=$files->fetchAll();
$history=db()->prepare('SELECT h.*,u.nama FROM pengajuan_status_history h LEFT JOIN users u ON u.id=h.diubah_oleh WHERE h.pengajuan_id=? ORDER BY h.created_at DESC');$history->execute([$id]);$history=$history->fetchAll();
?>
<div class="page-heading"><div><a class="text-link d-inline-block mb-2" href="<?= e(url('pengajuan')) ?>"><i class="bi bi-arrow-left me-1"></i>Kembali ke pengajuan</a><h1>Detail Pengajuan</h1><p><?= e($item['nomor_pengajuan']) ?> · Diajukan <?= e(format_datetime($item['diajukan_pada'])) ?></p></div><?= status_badge($item['status']) ?></div>
<div class="row g-4"><div class="col-xl-8"><section class="panel-card mb-4"><div class="panel-card-header"><h2 class="panel-title">Informasi Permohonan</h2></div><div class="panel-card-body"><div class="row g-4"><div class="col-md-6"><div class="detail-label">Nama pemohon</div><div class="detail-value"><?= e($item['nama_lengkap']) ?></div></div><div class="col-md-6"><div class="detail-label">NIK</div><div class="detail-value"><?= e($item['nik']) ?></div></div><div class="col-md-6"><div class="detail-label">Nomor telepon</div><div class="detail-value"><?= e($item['no_hp']??'-') ?></div></div><div class="col-md-6"><div class="detail-label">Jenis layanan</div><div class="detail-value"><?= e($item['nama_layanan']) ?></div></div><div class="col-12"><div class="detail-label">Alamat</div><div class="detail-value"><?= e($item['alamat']) ?></div></div><div class="col-12"><div class="detail-label">Keperluan</div><div class="detail-value"><?= e($item['keperluan']) ?></div></div><div class="col-12"><div class="detail-label">Keterangan tambahan</div><div class="detail-value"><?= nl2br(e($item['keterangan']?:'-')) ?></div></div><?php if($item['alasan_penolakan']): ?><div class="col-12"><div class="alert alert-danger mb-0"><strong>Alasan penolakan:</strong><br><?= nl2br(e($item['alasan_penolakan'])) ?></div></div><?php endif; ?></div></div></section>
<section class="panel-card"><div class="panel-card-header"><h2 class="panel-title">Dokumen Lampiran</h2></div><div class="panel-card-body"><?php if(!$files): ?><p class="text-muted-2 mb-0">Tidak ada dokumen lampiran.</p><?php else: foreach($files as $f): ?><a href="index.php?action=download_attachment&type=pengajuan&id=<?= (int)$f['id'] ?>" class="d-flex align-items-center gap-3 border rounded-3 p-3 mb-2"><i class="bi bi-file-earmark-pdf fs-3 text-army"></i><span class="flex-grow-1"><strong class="d-block"><?= e($f['nama_file_asli']) ?></strong><small class="text-muted-2"><?= e(number_format($f['ukuran_byte']/1024,1)) ?> KB</small></span><i class="bi bi-box-arrow-up-right"></i></a><?php endforeach; endif; ?></div></section></div>
<div class="col-xl-4"><section class="panel-card mb-4"><div class="panel-card-header"><h2 class="panel-title">Riwayat Status</h2></div><div class="panel-card-body"><div class="timeline"><?php foreach($history as $h): ?><div class="timeline-item"><strong class="d-block"><?= e(ucfirst($h['status'])) ?></strong><small class="text-muted-2"><?= e(format_datetime($h['created_at'])) ?> · <?= e($h['nama']??'Sistem') ?></small><p class="small text-muted-2 mb-0 mt-1"><?= e($h['catatan']??'') ?></p></div><?php endforeach; ?></div></div></section>
<?php if(in_array($item['status'],['menunggu','diproses','disetujui'],true)): ?><section class="panel-card"><div class="panel-card-header"><h2 class="panel-title">Tindak Lanjut</h2></div><div class="panel-card-body"><form method="post" action="index.php" class="vstack gap-3" data-disable-submit><?= csrf_field() ?><input type="hidden" name="action" value="update_pengajuan_status"><input type="hidden" name="return_page" value="detail-pengajuan"><input type="hidden" name="return_id" value="<?= $id ?>"><input type="hidden" name="id" value="<?= $id ?>"><div><label class="form-label">Ubah status</label><select class="form-select" name="status" required><?php foreach(['diproses'=>'Diproses','disetujui'=>'Disetujui','selesai'=>'Selesai','ditolak'=>'Ditolak'] as $v=>$label): ?><option value="<?= $v ?>" <?= $item['status']===$v?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><div><label class="form-label">Catatan / alasan</label><textarea class="form-control" name="catatan" rows="3" placeholder="Tulis catatan. Wajib diisi jika ditolak."></textarea></div><button class="btn btn-army">Simpan Status</button></form></div></section><?php endif; ?></div></div>
